{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A massive iron gate hangs crookedly under a broken arch, city lights reflecting in the glass diver's helmet.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer spreads a map on a cracked stone step.",
      "visual_description": "Mara kneels, unrolling a worn parchment map marked with symbols, her brass compass glinting.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning about the cursed tower.",
      "visual_description": "A crooked tower looms in twilight, the lamp's single eye glowing as its flame sputters.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The Sleeping Tax Collector naps on a pile of ledgers under a banner.",
      "visual_description": "An old royal banner hangs tattered above a dozing figure slumped on stamped papers.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scampers ahead into a dark alley.",
      "visual_description": "A small metal fox with a whirring tail dashes between shadowed walls, blue eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver swims through a reflective puddle into a hidden courtyard.",
      "visual_description": "The diver plunges into a shimmering puddle, emerging in a courtyard overgrown with vines.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara traces a route past an abandoned market stall.",
      "visual_description": "Mara points at a faded stall, her ink-stained fingers tracing a path on the map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The Oracle Lamp warns of a trap behind a magic door.",
      "visual_description": "A glowing door pulses with runes, the lamp's eye narrowing as it casts a red light.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector snores beneath a crumbling archway.",
      "visual_description": "A ledger pillow propped under the collector's head, stamped papers fluttering in the breeze.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The Tin Fox discovers a secret passage behind a loose stone.",
      "visual_description": "The fox's metal paw presses a stone that slides inward, revealing a dark corridor.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver peers through a mirror into a guarded hall.",
      "visual_description": "The diver's helmet presses against a cracked mirror, showing an empty hall with armored shapes.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara marks the location of a rumored escape route.",
      "visual_description": "Mara draws a line on the map with a charcoal stick, eyes fixed on a distant bridge.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The Oracle Lamp glows brighter as they approach the tower's base.",
      "visual_description": "The lamp's flame intensifies, casting long shadows against the tower's mossy foundation.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The Sleeping Tax Collector stirs but does not wake.",
      "visual_description": "The collector shifts, muttering in sleep, a stamped paper stuck to one sleeve.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The Tin Fox leads the group through a collapsed wall.",
      "visual_description": "The fox squeezes through a narrow gap in rubble, tail ticking as it guides the others.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver opens a magic door by reflecting a key.",
      "visual_description": "The diver holds up a reflective shard, casting a beam that unlocks a rune-covered door.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "Mara confirms the bridge is the only way out.",
      "visual_description": "Mara stands at the edge of a chasm, pointing at a stone bridge half-shrouded in mist.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across the bridge as the city crumbles behind.",
      "visual_description": "All five figures hurry across the bridge, the ruined city collapsing amid dust and falling banners.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ],
  "title": "The Mirror Rescue"
}

